import assert from 'node:assert/strict';
import test from 'node:test';
import { existsSync } from 'node:fs';
import { controlPlaneHtml } from './login-html.js';
import worker from './worker.js';

// The admin panel has exactly one implementation: the vanilla login shell
// generated by login-html.js and served by worker.js on every path. The
// React copy (App.jsx/main.jsx/lib/*) was removed in Phase 4 — it was
// reachable only via `vite dev`/`vite preview`, which no production path
// runs, and it duplicated these same three screens with zero feature
// delta. These tests guard the single implementation and the removal.

test('served HTML is the Control Plane login, not a stub', () => {
  const html = controlPlaneHtml('https://invexaretail.onrender.com');
  assert.match(html, /id="login-form"/);
  assert.match(html, /id="control-email"/);
  assert.match(html, /id="control-password"/);
  assert.match(html, />Sign in</);
  assert.match(html, /\/control\/v1\/auth\/login/);
  assert.match(html, /data-invexa="control-plane"/);
  assert.match(html, /<title>Invexa Control Plane<\/title>/);
  assert.equal(html.includes('Admin panel is ready'), false);
  assert.equal(html.includes('Invexa Retail Admin Panel'), false);
});

test('the login shell carries all three screens: login, company select, locked handoff', () => {
  const html = controlPlaneHtml('https://invexaretail.onrender.com');
  assert.match(html, /id="login-view"/);
  assert.match(html, /id="company-view"/);
  assert.match(html, /id="company-list"/);
  assert.match(html, /id="locked-view"/);
  assert.match(html, /\/control\/v1\/sessions\/select-company/);
});

test('the email field ships empty: no prefilled value, no credential-shaped placeholder', () => {
  const html = controlPlaneHtml('https://invexaretail.onrender.com');
  assert.equal(html.includes('superadmin@invexa.local'), false);
  const emailTag = html.match(/<input id="control-email"[^>]*>/)?.[0] ?? '';
  assert.notEqual(emailTag, '');
  assert.equal(emailTag.includes('value='), false);
  assert.equal(emailTag.includes('placeholder'), false);
});

test('Worker serves login HTML with no-store cache headers', async () => {
  const response = await worker.fetch(new Request('https://invexaretail.prateek160298.workers.dev/'), {
    VITE_API_BASE: 'https://invexaretail.onrender.com',
  });
  const html = await response.text();
  assert.equal(response.headers.get('x-invexa-panel'), 'control-plane');
  assert.match(response.headers.get('cache-control') || '', /no-store/);
  assert.match(html, /id="control-email"/);
  assert.match(html, />Sign in</);
});

test('Worker answers /health and OPTIONS without serving the login page', async () => {
  const health = await worker.fetch(new Request('https://invexaretail.prateek160298.workers.dev/health'), {});
  assert.equal(health.status, 200);
  assert.deepEqual(await health.json(), { ok: true, panel: 'control-plane' });
  const options = await worker.fetch(new Request('https://invexaretail.prateek160298.workers.dev/', { method: 'OPTIONS' }), {});
  assert.equal(options.status, 204);
});

test('locking a company hands the session off to the web app instead of rendering a dead-end panel', () => {
  const html = controlPlaneHtml('https://invexaretail.onrender.com', 'https://invexaretail.com');
  assert.match(html, /const WEB_APP_URL = "https:\/\/invexaretail\.com"/);
  assert.match(html, /window\.location\.href = WEB_APP_URL \+ "\/#\/control\?code=" \+ encodeURIComponent\(result\.code\)/);
  assert.match(html, /\/control\/v1\/sessions\/handoff/);
  assert.equal(html.includes('?session='), false, 'the session object never goes in the URL');
  assert.equal(html.includes('id="company-name"'), false);
  assert.equal(html.includes('id="locked-lede"'), false);
});

test('the dead React implementation stays deleted', () => {
  for (const dead of ['./App.jsx', './main.jsx', './index.css', './lib/api.js', './lib/session.js']) {
    assert.equal(existsSync(new URL(dead, import.meta.url)), false, `${dead} must not come back`);
  }
  assert.equal(existsSync(new URL('./login-html.js', import.meta.url)), true);
  assert.equal(existsSync(new URL('./worker.js', import.meta.url)), true);
});
